create extension if not exists postgis with schema extensions;create extension if not exists pgcrypto;
create table profiles(id uuid primary key references auth.users on delete cascade,display_name text not null,birth_date date not null check(birth_date<=current_date-interval '18 years'),bio text,location extensions.geography(point,4326),radius_km int not null default 50 check(radius_km between 1 and 50),verified boolean not null default false,created_at timestamptz default now());
create table likes(id uuid primary key default gen_random_uuid(),from_user uuid not null default auth.uid() references profiles on delete cascade,to_user uuid not null references profiles on delete cascade,created_at timestamptz default now(),unique(from_user,to_user));
create table matches(id uuid primary key default gen_random_uuid(),user_a uuid not null references profiles,user_b uuid not null references profiles,created_at timestamptz default now(),unique(user_a,user_b),check(user_a<user_b));
create table messages(id uuid primary key default gen_random_uuid(),match_id uuid not null references matches on delete cascade,sender_id uuid not null default auth.uid() references profiles,body text not null check(length(body) between 1 and 2000),created_at timestamptz default now());
create table blocks(id uuid primary key default gen_random_uuid(),blocker_id uuid not null default auth.uid() references profiles,blocked_id uuid not null references profiles,created_at timestamptz default now(),unique(blocker_id,blocked_id));
create table reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null default auth.uid() references profiles,reported_id uuid not null references profiles,reason text not null,details text,created_at timestamptz default now());
create table push_tokens(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references profiles,expo_token text unique not null,platform text check(platform in('ios','android')),created_at timestamptz default now());
create index profiles_location_gix on profiles using gist(location);create index messages_match_idx on messages(match_id,created_at);
create function is_match_member(mid uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from matches where id=mid and auth.uid() in(user_a,user_b))$$;
create function discover_profiles(p_lat float,p_lng float,p_limit int default 50) returns table(id uuid,display_name text,distance_km float) language sql stable security invoker set search_path=public,extensions as $$select p.id,p.display_name,st_distance(p.location,st_setsrid(st_makepoint(p_lng,p_lat),4326)::geography)/1000 from profiles p where p.id<>auth.uid() and p.location is not null and st_dwithin(p.location,st_setsrid(st_makepoint(p_lng,p_lat),4326)::geography,least(p.radius_km,50)*1000) and not exists(select 1 from blocks b where (b.blocker_id=auth.uid() and b.blocked_id=p.id)or(b.blocker_id=p.id and b.blocked_id=auth.uid())) limit least(p_limit,100)$$;
create function mutual_like() returns trigger language plpgsql security definer set search_path=public as $$begin if exists(select 1 from likes where from_user=new.to_user and to_user=new.from_user)then insert into matches(user_a,user_b)values(least(new.from_user,new.to_user),greatest(new.from_user,new.to_user))on conflict do nothing;end if;return new;end$$;create trigger likes_mutual after insert on likes for each row execute function mutual_like();
alter table profiles enable row level security;alter table likes enable row level security;alter table matches enable row level security;alter table messages enable row level security;alter table blocks enable row level security;alter table reports enable row level security;alter table push_tokens enable row level security;
create policy profiles_self on profiles for all using(id=auth.uid())with check(id=auth.uid());create policy profiles_read on profiles for select using(auth.uid() is not null);create policy likes_write on likes for insert with check(from_user=auth.uid());create policy likes_read on likes for select using(auth.uid() in(from_user,to_user));create policy matches_read on matches for select using(auth.uid() in(user_a,user_b));create policy messages_read on messages for select using(is_match_member(match_id));create policy messages_write on messages for insert with check(sender_id=auth.uid() and is_match_member(match_id));create policy blocks_owner on blocks for all using(blocker_id=auth.uid())with check(blocker_id=auth.uid());create policy reports_write on reports for insert with check(reporter_id=auth.uid());create policy push_owner on push_tokens for all using(user_id=auth.uid())with check(user_id=auth.uid());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('avatars','avatars',false,10485760,array['image/jpeg','image/png','image/webp'])on conflict do nothing;create policy avatar_read on storage.objects for select using(bucket_id='avatars' and auth.uid() is not null);create policy avatar_write on storage.objects for insert with check(bucket_id='avatars' and(storage.foldername(name))[1]=auth.uid()::text);create policy avatar_delete on storage.objects for delete using(bucket_id='avatars' and owner_id=auth.uid()::text);alter publication supabase_realtime add table messages;
